export const GLOSSARY_SHARD = Object.freeze({"cryptocurrency":{"slug":"cryptocurrency","cat":"basics","en":"Cryptocurrency","contentLocale":"ko","term":"암호화폐(Cryptocurrency)","aka":["가상자산","가상화폐","코인","크립토"],"short":"암호화폐는 블록체인 위에서 암호 기술로 소유권과 거래를 증명하는 디지털 자산으로, 중앙은행이 아닌 네트워크 규칙에 따라 발행되고 전송됩니다.","body":[["암호화폐는 은행 계좌 대신 ",["지갑 주소","wallet-address"],"와 ",["개인 키","private-key"],"로 관리합니다. 개인 키를 가진 사람만 그 주소의 자산을 옮길 수 있고, 모든 이동 기록은 ",["블록체인","blockchain"],"에 남습니다. 국내에서는 법률과 ",["거래소","centralized-exchange"]," 화면에서 가상자산이라는 표현을 주로 씁니다."],["종류는 다양합니다. ",["비트코인","bitcoin"],"처럼 가치 저장과 송금에 초점을 둔 자산, ",["이더리움","ethereum"],"처럼 스마트 컨트랙트를 실행하는 플랫폼 코인, 달러 가치에 연동된 스테이블코인, 특정 서비스 안에서 쓰이는 토큰 등이 있습니다."],"가격은 수요와 공급으로 정해지며 주식보다 변동성이 큰 편입니다. 24시간 거래되고, 거래소마다 상장 종목과 수수료, 입출금 네트워크가 다릅니다. 과세나 규제도 나라마다 달라 거주 국가의 규칙을 따로 확인해야 합니다."],"example":"국내 원화마켓 거래소에서 100만 원으로 비트코인을 산다고 해 보겠습니다. 1 BTC가 1억 원이라면 0.01 BTC를 받게 되고, 거래 수수료율이 0.05%라고 가정하면 약 500원이 수수료로 빠집니다. 이 0.01 BTC를 개인 지갑으로 옮기면 거래소가 아닌 본인이 개인 키로 직접 관리하게 됩니다.","mistakes":["암호화폐를 사면 무조건 1개 단위로 사야 한다고 생각하지만, 대부분 소수점 단위로 나눠 살 수 있습니다.","거래소 계정에 보이는 잔고와 개인 키로 직접 관리하는 자산의 차이를 모르고 넘어갑니다.","이름이 비슷한 코인을 같은 자산으로 착각해 엉뚱한 종목을 매수합니다."],"faq":[{"q":"가상자산과 암호화폐는 다른 말인가요?","a":"일상적으로는 같은 대상을 가리킵니다. 한국 법령과 거래소는 가상자산이라는 용어를 주로 쓰고, 기술적인 맥락에서는 암호화폐라는 표현을 많이 씁니다."},{"q":"암호화폐는 누가 발행하나요?","a":"비트코인처럼 채굴 규칙에 따라 자동으로 발행되는 경우도 있고, 프로젝트 팀이나 재단이 토큰을 발행하는 경우도 있습니다. 스테이블코인은 테더(USDT), 서클(USDC)처럼 발행사가 따로 있습니다."}],"title":"암호화폐란? 가상자산 뜻과 종류 정리","description":"암호화폐(가상자산)의 뜻, 지갑과 개인 키로 관리하는 방식, 코인 종류와 거래소별 차이를 초보자 눈높이로 설명합니다.","related":[["blockchain","블록체인(Blockchain)","블록체인은 거래 기록을 블록 단위로 묶어 시간 순서대로 연결하고, 여러 컴퓨터가 같은 사본을 나눠 보관하는 분산 장부입니다."],["bitcoin","비트코인(Bitcoin, BTC)","비트코인(BTC)은 2009년 운영을 시작한 최초의 암호화폐로, 작업증명 블록체인 위에서 중앙 관리자 없이 발행되며 총발행량이 2,100만 개로 정해져 있습니다."],["altcoin","알트코인(Altcoin)","알트코인은 비트코인을 제외한 나머지 암호화폐를 통틀어 부르는 말로, 이더리움, 솔라나, XRP 같은 대형 코인부터 소형 토큰까지 모두 포함합니다."],["stablecoin","스테이블코인(Stablecoin)","스테이블코인은 미국 달러 같은 법정화폐나 다른 자산의 가치에 가격을 고정하도록 설계된 암호화폐로, USDT와 USDC가 대표적입니다."],["centralized-exchange","중앙화 거래소(CEX)","중앙화 거래소(CEX)는 회사가 운영하며 사용자의 자산을 보관하고 주문을 자체 시스템에서 체결해 주는 암호화폐 거래소입니다."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"비트코인 한 개가 그렇게 비싼데, 조금만 살 수도 있나요?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"smart-contract":{"slug":"smart-contract","cat":"basics","en":"Smart contract","contentLocale":"ko","term":"스마트 컨트랙트(Smart Contract)","aka":["스마트 계약","Smart Contract","컨트랙트"],"short":"스마트 컨트랙트는 블록체인에 배포되어 미리 정한 조건이 충족되면 자동으로 실행되는 프로그램으로, 중개자 없이 거래와 규칙을 처리합니다.","body":[["스마트 컨트랙트는 만약 A가 일어나면 B를 실행한다는 식의 코드를 ",["블록체인","blockchain"],"에 올려 둔 것입니다. 한 번 배포되면 누구나 같은 코드를 호출할 수 있고, 결과는 블록체인에 기록됩니다. ",["이더리움","ethereum"],"이 이 개념을 대중화했습니다."],[["탈중앙화 거래소","dex"],", 대출 프로토콜, ",["스테이블코인","stablecoin"],", ",["NFT","nft"],", 토큰 발행이 모두 스마트 컨트랙트로 작동합니다. 사용자가 컨트랙트를 실행할 때는 그 체인의 기본 코인으로 ",["가스비","gas-fee"],"를 냅니다."],"코드가 곧 규칙이기 때문에 버그가 있으면 그대로 악용될 수 있습니다. 또 지갑에서 컨트랙트에 토큰 사용 권한(승인)을 주면 그 컨트랙트가 토큰을 옮길 수 있게 됩니다. 감사 보고서가 있는지, 승인 범위가 적절한지 확인하는 것이 기본 보안 습관입니다."],"example":"DEX에서 1,000 USDC를 ETH로 바꾸는 상황을 보겠습니다. 먼저 USDC 컨트랙트에 DEX가 1,000 USDC를 쓸 수 있도록 승인 트랜잭션을 보내고, 다음으로 교환 트랜잭션을 보냅니다. ETH 가격이 2,500 USDC이고 풀 수수료가 0.3%라면 수수료 3 USDC를 뺀 997 USDC로 약 0.3988 ETH를 받습니다. 두 트랜잭션 모두 가스비가 별도로 듭니다.","mistakes":["토큰 승인을 무제한으로 허용한 뒤 사용하지 않는 서비스의 권한을 취소하지 않습니다.","스마트 컨트랙트는 자동이라 안전하다고 생각하고 감사 여부나 운영 이력을 확인하지 않습니다.","지갑 서명 요청의 내용을 읽지 않고 습관적으로 승인 버튼을 누릅니다."],"faq":[{"q":"스마트 컨트랙트는 수정할 수 있나요?","a":"기본적으로 배포된 코드는 바뀌지 않지만, 업그레이드 가능한 구조로 설계된 컨트랙트는 관리자가 로직을 교체할 수 있습니다. 이 경우 관리자 권한이 누구에게 있는지가 중요한 확인 포인트입니다."},{"q":"비트코인에도 스마트 컨트랙트가 있나요?","a":"비트코인도 제한적인 스크립트 기능은 있지만, 이더리움처럼 복잡한 프로그램을 자유롭게 실행하는 용도로 설계되지는 않았습니다."}],"title":"스마트 컨트랙트란? 뜻과 작동 방식","description":"스마트 컨트랙트의 뜻과 작동 방식, DEX·대출 등 활용 사례, 토큰 승인과 코드 버그 같은 보안 체크 포인트를 정리합니다.","related":[["ethereum","이더리움(Ethereum, ETH)","이더리움(ETH)은 스마트 컨트랙트를 실행할 수 있는 블록체인 플랫폼이며, ETH는 그 네트워크에서 가스비를 내고 스테이킹에 쓰이는 기본 코인입니다."],["defi","디파이(DeFi, 탈중앙화 금융)","디파이(DeFi)는 은행이나 거래소 같은 중개자 없이 블록체인 위 스마트 컨트랙트로 거래, 대출, 예치 같은 금융 서비스를 제공하는 생태계입니다."],["token-approval","토큰 승인(Token Approval, 허용량)","토큰 승인은 스마트 컨트랙트가 내 지갑의 특정 토큰을 정해진 한도만큼 대신 옮길 수 있도록 허락하는 서명으로, 한 번 주면 취소하기 전까지 유지됩니다."],["oracle","블록체인 오라클(Oracle)","블록체인 오라클은 코인 가격, 환율, 경기 결과처럼 블록체인 밖에 있는 데이터를 스마트 컨트랙트가 읽을 수 있도록 체인 위로 전달하는 시스템입니다."],["gas-fee","가스비(Gas Fee)","가스비는 블록체인에서 송금이나 스마트 컨트랙트를 실행할 때 검증자나 채굴자에게 내는 네트워크 수수료로, 보통 그 체인의 기본 코인으로 지불합니다."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"gas-fee":{"slug":"gas-fee","cat":"basics","en":"Gas fee","contentLocale":"ko","term":"가스비(Gas Fee)","aka":["가스 수수료","Gas","네트워크 수수료"],"short":"가스비는 블록체인에서 송금이나 스마트 컨트랙트를 실행할 때 검증자나 채굴자에게 내는 네트워크 수수료로, 보통 그 체인의 기본 코인으로 지불합니다.","body":[["가스는 ",["블록체인","blockchain"],"에서 작업량을 재는 단위입니다. 단순 송금은 가스를 적게 쓰고, ",["DEX","dex"]," 교환처럼 복잡한 ",["컨트랙트","smart-contract"]," 실행은 많이 씁니다. ",["이더리움","ethereum"],"에서 가스비는 사용한 가스량에 가스 가격(기본 수수료와 우선 수수료의 합)을 곱해 정해집니다."],"네트워크가 붐비면 가스 가격이 올라가 같은 작업이라도 수수료가 몇 배로 뛸 수 있습니다. 가스비를 너무 낮게 설정하면 거래가 오래 대기하거나 처리되지 않을 수 있습니다. 거래가 실패해도 이미 쓴 가스비는 돌려받지 못합니다.",[["거래소","centralized-exchange"]," ",["출금 수수료","withdrawal-fee"],"는 가스비와 비슷해 보이지만 거래소가 정한 고정 수수료인 경우가 많습니다. 출금 네트워크를 레이어2나 수수료가 낮은 체인으로 고르면 비용을 줄일 수 있지만, 받는 쪽이 같은 네트워크를 지원하는지 먼저 확인해야 합니다."]],"example":"이더리움에서 토큰 교환에 가스 150,000이 필요하고 가스 가격이 20 gwei라고 가정합니다. 가스비는 150,000 곱하기 20 gwei, 즉 3,000,000 gwei이며 이는 0.003 ETH입니다. ETH 가격이 3,000달러라면 약 9달러입니다. 네트워크가 혼잡해 가스 가격이 60 gwei로 오르면 같은 작업에 0.009 ETH, 약 27달러가 듭니다.","mistakes":["지갑에 기본 코인이 없어서 토큰을 보내지 못하는 상황을 만듭니다.","실패한 트랜잭션의 가스비는 환불된다고 오해합니다.","거래소 출금 수수료와 온체인 가스비를 같은 것으로 생각해 네트워크를 비교하지 않습니다."],"faq":[{"q":"가스비는 왜 매번 다른가요?","a":"네트워크 사용 수요에 따라 가스 가격이 실시간으로 바뀌기 때문입니다. 작업의 복잡도에 따라 필요한 가스량도 달라집니다."},{"q":"gwei는 무엇인가요?","a":"gwei는 ETH의 작은 단위로, 1 gwei는 0.000000001 ETH입니다. 이더리움 가스 가격을 표시할 때 주로 사용합니다."}],"title":"가스비(Gas Fee)란? 뜻과 계산법 정리","description":"가스비의 뜻과 이더리움 가스비 계산법, gwei 단위, 가스비가 오르는 이유와 수수료를 줄이는 네트워크 선택 요령을 설명합니다.","related":[["layer-2","레이어2(Layer 2, L2)","레이어2(L2)는 레이어1 블록체인 위에서 거래를 더 빠르고 저렴하게 처리한 뒤, 그 결과를 레이어1에 기록해 보안을 이어받는 확장 네트워크입니다."],["mempool","멤풀(Mempool)","멤풀은 블록에 아직 포함되지 않은 거래들이 노드마다 대기하는 공간으로, 채굴자나 검증자가 여기서 거래를 골라 블록을 만듭니다."],["withdrawal-fee","출금 수수료","출금 수수료는 거래소에서 코인을 외부 지갑이나 다른 거래소로 보낼 때 출금 수량에서 차감되는 비용으로, 코인과 네트워크마다 다르게 정해집니다."],["ethereum","이더리움(Ethereum, ETH)","이더리움(ETH)은 스마트 컨트랙트를 실행할 수 있는 블록체인 플랫폼이며, ETH는 그 네트워크에서 가스비를 내고 스테이킹에 쓰이는 기본 코인입니다."],["smart-contract","스마트 컨트랙트(Smart Contract)","스마트 컨트랙트는 블록체인에 배포되어 미리 정한 조건이 충족되면 자동으로 실행되는 프로그램으로, 중개자 없이 거래와 규칙을 처리합니다."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"코인 전송 전: 이 항목들은 절대 어림짐작하지 마세요"},"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"bull-market":{"slug":"bull-market","cat":"basics","en":"Bull market","contentLocale":"ko","term":"상승장(Bull Market, 불장)","aka":["불장","강세장","Bull Market"],"short":"상승장은 가격이 비교적 긴 기간 동안 전반적으로 오르고 투자 심리가 낙관적인 시장 국면으로, 코인 커뮤니티에서는 흔히 불장이라고 부릅니다.","body":[["상승장에는 고점과 저점이 함께 높아지는 흐름이 이어지고, ",["거래량","trading-volume"],"과 신규 투자자 유입이 늘어나는 경우가 많습니다. 주식시장에서는 저점 대비 20% 이상 상승을 하나의 기준으로 쓰기도 하지만, ",["변동성","volatility"],"이 큰 ",["암호화폐","cryptocurrency"]," 시장에서는 정해진 공식적인 기준이 없습니다."],["상승장에서도 중간에 20~30% 수준의 조정이 자주 나옵니다. ",["레버리지","leverage"],"를 크게 쓰면 큰 흐름은 맞혀도 중간 조정에서 ",["강제청산","liquidation"],"을 당할 수 있습니다. 상승장 분위기에서는 손절 기준이 느슨해지고 포지션이 커지기 쉬워 오히려 리스크 관리가 더 중요합니다."],["상승장 여부는 지나고 나서야 명확해지는 경우가 많습니다. 이동평균선, 거래량, 자금 흐름, ",["공포탐욕지수","fear-and-greed-index"]," 같은 지표를 참고할 수 있지만 어느 하나로 단정할 수는 없습니다."]],"example":"BTC가 40,000 USDT에서 70,000 USDT까지 오르는 상승장 중에 62,000 USDT에서 10배 레버리지로 롱 포지션을 열었다고 가정해 보겠습니다. 가격이 약 10% 하락해 55,800 USDT 부근에 오면 증거금 대부분을 잃고 청산될 수 있습니다. 이후 가격이 70,000 USDT로 회복해도 이미 청산된 포지션은 이익을 얻지 못합니다. 실제 청산 가격은 유지 증거금률과 수수료에 따라 조금 더 가깝습니다.","mistakes":["상승장이라는 이유로 손절 없이 레버리지를 높게 씁니다.","상승장 막바지에 주변 수익 인증만 보고 뒤늦게 큰 금액을 한 번에 넣습니다.","모든 코인이 상승장에서 함께 오른다고 생각하고 종목별 차이를 보지 않습니다."],"faq":[{"q":"불장과 상승장은 같은 말인가요?","a":"같은 뜻입니다. 영어 bull market에서 나온 말로, 황소가 뿔을 위로 치켜올리는 모습에 빗댄 표현입니다."},{"q":"상승장이 시작됐는지 어떻게 알 수 있나요?","a":"고점과 저점이 높아지는 추세, 거래량 증가, 장기 이동평균선 위에서의 가격 유지 등을 참고합니다. 다만 어떤 지표도 상승장을 확정해 주지는 않습니다."}],"title":"상승장(불장)이란? 뜻과 주의할 점","description":"상승장(불장)의 뜻과 특징, 상승장 중 조정에서 레버리지 포지션이 청산되는 이유, 상승장 리스크 관리 요령을 설명합니다.","related":[["bear-market","하락장(Bear Market, 베어장)","하락장은 가격이 비교적 긴 기간 동안 전반적으로 내려가고 투자 심리가 비관적인 시장 국면으로, 베어장 또는 약세장이라고도 부릅니다."],["fomo","포모(FOMO)","포모(FOMO)는 Fear Of Missing Out의 약자로, 남들이 다 버는 기회를 나만 놓칠까 봐 불안해서 충분한 판단 없이 급하게 매수하는 심리를 말합니다."],["all-time-high","역대 최고가(ATH)","역대 최고가(ATH)는 어떤 자산이 거래를 시작한 이후 기록한 가장 높은 가격으로, 코인 커뮤니티에서는 전고점이나 신고가라는 표현도 함께 씁니다."],["fear-and-greed-index","공포 탐욕 지수(Fear and Greed Index)","공포 탐욕 지수는 가격 변동성, 거래량, 소셜 미디어 반응 같은 데이터를 0에서 100 사이 점수로 묶어 시장 심리를 보여 주는 지표입니다."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"take-profit":{"slug":"take-profit","cat":"trading","en":"Take-profit order","contentLocale":"ko","term":"익절 주문(Take-Profit)","aka":["익절","테이크프로핏","TP","Take Profit"],"short":"익절 주문(테이크프로핏)은 가격이 미리 정한 목표 수준에 도달하면 자동으로 포지션을 정리해 이익을 확정하는 주문입니다.","body":[["익절 주문은 ",["롱 포지션","long-and-short"],"이라면 ",["현재가","last-price"],"보다 위에, 숏 포지션이라면 아래에 목표 가격을 둡니다. 가격이 목표에 닿으면 ",["시장가","market-order"],"나 ",["지정가","limit-order"],"로 정리됩니다. 화면을 계속 보지 않아도 계획한 가격에서 이익을 실현할 수 있다는 것이 장점입니다."],["많은 ",["거래소","centralized-exchange"],"는 포지션을 열 때 익절(TP)과 손절(SL)을 함께 설정하는 기능을 제공합니다. 둘 중 하나가 실행되면 다른 하나는 자동으로 취소되는 구조가 일반적이며, 현물에서는 ",["OCO 주문","oco-order"],"으로 비슷하게 구성할 수 있습니다."],"목표가를 정할 때는 손익비를 함께 봅니다. 손절 폭보다 익절 폭이 너무 작으면 승률이 높아도 장기적으로 손실이 날 수 있습니다. 물량을 나눠 일부는 1차 목표에서, 나머지는 2차 목표에서 정리하는 분할 익절도 많이 씁니다."],"example":"ETH를 2,400 USDT에 1 ETH 매수하고 손절은 2,280 USDT, 익절은 2,700 USDT에 걸었다고 가정해 보겠습니다. 손절 폭은 120 USDT, 익절 폭은 300 USDT로 손익비는 1대 2.5입니다. 0.5 ETH는 2,550 USDT에서, 나머지 0.5 ETH는 2,700 USDT에서 분할 익절한다면 총 이익은 75 더하기 150, 즉 225 USDT입니다(수수료 제외).","mistakes":["익절 목표를 정하지 않고 계속 들고 있다가 상승분을 모두 반납합니다.","손절 폭은 넓게, 익절 폭은 좁게 잡아 손익비가 불리한 거래를 반복합니다.","TP 주문 체결 후 남은 SL 주문이 자동으로 취소됐는지 확인하지 않습니다."],"faq":[{"q":"익절과 손절을 동시에 걸 수 있나요?","a":"대부분의 거래소에서 가능합니다. 선물에서는 TP/SL 기능으로, 현물에서는 OCO 주문으로 설정할 수 있으며 구체적인 방식은 거래소마다 다릅니다."},{"q":"분할 익절은 왜 하나요?","a":"목표 가격에 다 도달하지 못하고 되돌아오는 경우를 대비해 일부 이익을 먼저 확정하기 위해서입니다. 대신 끝까지 오를 경우 전체 이익은 줄어듭니다."}],"title":"익절 주문(TP)이란? 뜻과 설정 방법","description":"익절 주문(테이크프로핏)의 뜻과 설정 방법, 손절과 함께 쓰는 TP/SL, 손익비와 분할 익절 계산 예시를 정리합니다.","related":[["stop-loss","손절 주문(Stop-Loss)","손절 주문(스탑로스)은 가격이 미리 정한 수준까지 불리하게 움직이면 자동으로 포지션을 정리해 손실을 제한하는 주문입니다."],["oco-order","OCO 주문(One-Cancels-the-Other)","OCO 주문은 두 개의 주문을 묶어 하나가 체결되면 나머지 하나가 자동으로 취소되도록 하는 주문 방식으로, 익절과 손절을 동시에 걸 때 주로 씁니다."],["risk-reward-ratio","손익비(Risk-Reward Ratio)","손익비는 한 번의 거래에서 감수하는 손실 폭(진입가와 손절가의 차이)과 기대하는 수익 폭(진입가와 익절가의 차이)을 비교한 비율입니다."],["limit-order","지정가 주문(Limit Order)","지정가 주문은 사거나 팔 가격을 직접 정해 두고, 시장 가격이 그 가격이나 더 유리한 가격에 도달했을 때만 체결되는 주문입니다."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"익절과 손절은 계획이지 보험이 아니다"},"coin":null,"tool":null,"cta":false},"margin-trading":{"slug":"margin-trading","cat":"derivatives","en":"Margin trading","contentLocale":"ko","term":"마진 거래(Margin Trading)","aka":["마진 트레이딩","증거금 거래","margin trading"],"short":"마진 거래는 계좌의 자산을 증거금으로 맡기고 거래소에서 자금을 빌려 보유 자금보다 큰 규모로 사거나, 코인을 빌려 팔아 하락에 베팅하는 거래입니다.","body":[["좁은 의미의 마진 거래는 현물 마진을 말합니다. 증거금을 맡기고 USDT를 빌려 코인을 더 사거나, 코인을 빌려 팔아 ",["숏 포지션","long-and-short"],"을 만듭니다. 빌린 자산에는 시간 단위로 이자가 붙습니다."],["넓은 의미로는 선물처럼 증거금을 맡기고 ",["레버리지","leverage"],"를 쓰는 거래 전체를 마진 거래라고 부르기도 합니다. 선물은 이자 대신 ",["펀딩비","funding-rate"],"가 있고, 현물 마진은 실제 코인을 빌리고 갚는다는 점이 다릅니다."],["어느 방식이든 손실이 커져 증거금 비율이 ",["거래소","centralized-exchange"],"가 정한 기준 아래로 떨어지면 ",["강제청산","liquidation"],"됩니다. ",["격리 마진","isolated-margin"],"과 교차 마진 중 무엇을 쓰는지에 따라 위험이 한 포지션에 머물지 계좌 전체로 번질지가 달라집니다."]],"example":"1,000 USDT를 증거금으로 맡기고 3배 현물 마진으로 2,000 USDT를 빌려 BTC를 총 3,000 USDT어치 샀다고 가정해 보겠습니다. 차입 이자가 하루 0.02%라면 하루 이자는 2,000 × 0.02% = 0.4 USDT, 30일이면 12 USDT입니다. BTC가 10% 오르면 이익은 300 USDT에서 이자 12를 빼 288 USDT이고, 10% 떨어지면 손실은 312 USDT로 증거금의 약 31%가 사라집니다.","mistakes":["빌린 자금의 이자를 계산하지 않고 오래 보유해 이자가 수익을 갉아먹습니다.","현물 마진과 선물을 같은 것으로 생각해 이자와 펀딩비 구조를 혼동합니다.","교차 마진에서 계좌 전체가 담보로 잡힌다는 사실을 모르고 큰 포지션을 엽니다."],"faq":[{"q":"마진 거래와 선물 거래는 같은 건가요?","a":"둘 다 증거금과 레버리지를 쓰지만, 현물 마진은 실제 자산을 빌려 이자를 내고 선물은 계약을 거래하며 펀딩비를 주고받습니다. 거래소에서도 메뉴가 따로 있는 경우가 많습니다."},{"q":"마진 거래로 원금보다 많이 잃을 수 있나요?","a":"보통은 청산 시스템이 증거금 범위 안에서 포지션을 정리합니다. 다만 급격한 가격 변동 시 손실 처리 방식은 거래소 규정에 따라 다르므로 확인이 필요합니다."}],"title":"마진 거래란? 현물 마진과 선물의 차이","description":"마진 거래의 뜻, 자금을 빌려 거래하는 구조와 이자, 선물과의 차이, 강제청산 위험을 예시로 설명합니다.","related":[["leverage","레버리지(Leverage)","레버리지는 맡긴 증거금보다 몇 배 큰 규모의 포지션을 거래하는 것으로, 수익과 손실이 모두 그 배수만큼 커지고 강제청산 위험도 함께 커집니다."],["initial-margin","초기 증거금(Initial Margin)","초기 증거금은 레버리지 포지션을 새로 열 때 담보로 맡겨야 하는 최소 금액으로, 보통 포지션 규모를 레버리지 배수로 나눈 값입니다."],["maintenance-margin","유지 증거금(Maintenance Margin)","유지 증거금은 레버리지 포지션을 계속 유지하기 위해 계좌에 남아 있어야 하는 최소 증거금으로, 증거금이 이 수준 아래로 떨어지면 강제청산이 시작됩니다."],["liquidation","강제청산(Liquidation)","강제청산은 레버리지 포지션의 손실로 증거금이 유지 증거금 아래로 떨어졌을 때 거래소가 더 큰 손실을 막기 위해 포지션을 강제로 정리하는 것입니다."],["cross-margin","교차 마진(Cross Margin)","교차 마진은 계좌의 사용 가능한 잔고 전체를 여러 포지션이 함께 증거금으로 쓰는 방식으로, 청산가는 멀어지지만 한 번 청산되면 계좌 잔고 대부분을 잃을 수 있습니다."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10배 레버리지: 돈이 늘어나는가, 리스크가 커지는가?"},"coin":null,"tool":null,"cta":false},"non-custodial-wallet":{"slug":"non-custodial-wallet","cat":"wallets-security","en":"Non-custodial (self-custody) wallet","contentLocale":"ko","term":"비수탁형 지갑(Non-custodial Wallet, 개인 지갑)","aka":["개인 지갑","셀프 커스터디 지갑","논커스터디얼 지갑","non-custodial wallet"],"short":"비수탁형 지갑은 거래소 같은 제3자가 아니라 사용자 본인이 개인 키와 시드 문구를 직접 보관하고 관리하는 암호화폐 지갑입니다.","body":[[["거래소","centralized-exchange"]," 계정에 코인을 두면 실제 ",["개인 키","private-key"],"는 거래소가 들고 있고, 사용자는 거래소 장부상의 잔고를 보는 셈입니다. 반면 메타마스크, 팬텀, 트러스트 월렛 같은 비수탁형 지갑은 지갑을 만들 때 생성되는 ",["시드 문구","seed-phrase"],"와 개인 키를 사용자 기기에만 저장합니다. 자산을 옮기거나 서명할 권한이 오직 본인에게 있다는 뜻입니다."],"장점은 거래소 출금 정지나 파산 같은 상황에서도 자산 통제권을 잃지 않는다는 점이고, DeFi나 디앱을 직접 이용할 수 있다는 점입니다. 대신 비밀번호 찾기 기능이 없습니다. 시드 문구를 잃어버리거나 유출되면 누구도 자산을 되찾아 줄 수 없습니다.","그래서 비수탁형 지갑은 백업 습관이 핵심입니다. 시드 문구는 종이나 금속판에 오프라인으로 적어 두고, 사진이나 클라우드 메모에 저장하지 않는 것이 기본입니다."],"example":["거래소에 2,000 USDT가 있고 이 중 1,500 USDT를 개인 지갑으로 옮긴다고 가정합니다. ",["출금 수수료","withdrawal-fee"],"가 1 USDT라면 지갑에는 1,499 USDT가 도착합니다. 이제 이 1,499 USDT는 거래소 계정이 잠겨도 영향을 받지 않지만, 휴대폰을 잃어버렸는데 시드 문구 12단어를 백업하지 않았다면 1,499 ",["USDT","usdt"]," 전체에 다시 접근할 방법이 없습니다."],"mistakes":["지갑 앱 비밀번호만 기억하고 시드 문구는 따로 적어 두지 않습니다.","시드 문구를 휴대폰 사진첩이나 카카오톡 나에게 보내기에 저장해 둡니다.","고객센터라고 주장하는 사람에게 지갑 복구를 도와 달라며 시드 문구를 알려 줍니다."],"faq":[{"q":"비수탁형 지갑과 거래소 지갑의 차이는 무엇인가요?","a":"거래소 지갑은 거래소가 개인 키를 보관하고, 비수탁형 지갑은 사용자가 직접 보관합니다. 통제권이 커지는 만큼 백업과 보안 책임도 사용자에게 넘어옵니다."},{"q":"시드 문구를 잃어버리면 복구할 수 있나요?","a":"지갑 앱이 기기에 남아 있다면 그 안에서 시드 문구를 다시 확인할 수 있는 경우도 있습니다. 하지만 기기와 시드 문구를 모두 잃으면 지갑 회사도 복구해 줄 수 없습니다."}],"title":"비수탁형 지갑이란? 개인 지갑의 뜻과 장단점","description":"비수탁형(개인) 지갑의 뜻, 거래소 지갑과의 차이, 시드 문구 백업이 왜 중요한지 쉽게 정리합니다.","related":[["custodial-wallet","수탁형 지갑(Custodial Wallet)","수탁형 지갑은 거래소나 서비스 업체가 개인 키를 대신 보관하고 관리하는 지갑으로, 이용자는 아이디와 비밀번호로 접근하지만 코인의 직접 통제권은 업체에 있습니다."],["seed-phrase","시드 문구(Seed Phrase, 복구 문구)","시드 문구는 지갑을 만들 때 생성되는 12개 또는 24개의 영어 단어 목록으로, 이것만 있으면 지갑의 모든 개인 키와 자산을 복구할 수 있는 마스터 키입니다."],["private-key","개인 키(Private Key)","개인 키는 블록체인 주소의 자산을 사용할 수 있게 해 주는 비밀 숫자로, 이 키로 거래에 서명해야 송금이 이뤄집니다."],["hardware-wallet","하드웨어 지갑(Hardware Wallet)","하드웨어 지갑은 개인 키를 전용 보안 기기 안에 보관하고 거래 서명도 기기 안에서 처리해 키가 컴퓨터나 휴대폰에 노출되지 않게 하는 지갑입니다."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"내 코인은 어디에 있을까: 거래소 vs 지갑"},"coin":null,"tool":null,"cta":false},"multisig-wallet":{"slug":"multisig-wallet","cat":"wallets-security","en":"Multisig wallet","contentLocale":"ko","term":"멀티시그 지갑(Multisig Wallet)","aka":["다중 서명 지갑","멀티시그","multisig"],"short":"멀티시그 지갑은 여러 개의 개인 키 가운데 정해진 수 이상이 함께 서명해야 송금할 수 있는 지갑으로, 키 하나가 유출돼도 자산을 옮길 수 없게 합니다.","body":[["멀티시그는 보통 3개 중 2개, 5개 중 3개처럼 표시합니다. 3개 중 2개 구조라면 키를 세 곳에 나눠 두고 그중 두 개의 서명이 모여야 거래가 실행됩니다. ",["이더리움","ethereum"]," 계열에서는 Safe 같은 ",["스마트 컨트랙트","smart-contract"]," 지갑이 널리 쓰입니다."],["장점은 단일 실패 지점을 없앤다는 것입니다. 키 하나를 잃어도 나머지 키로 자산을 옮길 수 있고, 키 하나가 해킹돼도 혼자서는 출금할 수 없습니다. 그래서 ",["DAO","dao"]," 금고, 프로젝트 자금, 법인 자산, 큰 금액의 개인 보관에 자주 쓰입니다."],"대신 설정과 서명 절차가 복잡하고, 체인마다 지원 방식이 다릅니다. 서명자들이 모두 같은 가짜 화면에 속아 서명하면 멀티시그도 지켜 주지 못하므로, 각 서명자가 거래 내용을 독립적으로 확인해야 합니다."],"example":"프로젝트 금고에 200만 USDC가 있고 3개 중 2개 멀티시그로 관리한다고 가정합니다. 키는 대표, 재무 담당, 외부 고문이 하나씩 갖고 있습니다. 대표의 노트북이 해킹돼 키 하나가 유출돼도 공격자는 서명 1개만 만들 수 있어 200만 USDC를 옮기지 못합니다. 반대로 재무 담당이 키를 잃어버려도 대표와 고문의 서명 2개로 자금을 새 멀티시그로 이전할 수 있습니다.","mistakes":["멀티시그 키 여러 개를 같은 컴퓨터나 같은 사람에게 몰아 둡니다.","다른 서명자가 먼저 서명했다는 이유로 거래 내용을 확인하지 않고 서명합니다.","지원하지 않는 체인으로 멀티시그 주소에 자산을 보냅니다."],"faq":[{"q":"개인도 멀티시그 지갑을 써야 하나요?","a":"필수는 아니지만 금액이 크다면 하드웨어 지갑 여러 개를 묶은 멀티시그로 단일 키 위험을 줄일 수 있습니다. 대신 관리 절차가 복잡해집니다."},{"q":"멀티시그 키 하나를 잃어버리면 어떻게 되나요?","a":"필요한 서명 수 이상의 키가 남아 있으면 자산을 옮기거나 서명자를 교체할 수 있습니다. 남은 키가 기준보다 적으면 자산에 접근할 수 없습니다."}],"title":"멀티시그 지갑이란? 다중 서명 원리와 활용","description":"멀티시그(다중 서명) 지갑의 작동 원리, 2-of-3 구조의 장점, DAO와 개인이 활용하는 방법과 주의점을 정리합니다.","related":[["private-key","개인 키(Private Key)","개인 키는 블록체인 주소의 자산을 사용할 수 있게 해 주는 비밀 숫자로, 이 키로 거래에 서명해야 송금이 이뤄집니다."],["cold-wallet","콜드월렛(Cold Wallet, 콜드 스토리지)","콜드월렛은 개인 키를 인터넷과 분리된 환경에 보관해 온라인 해킹 위험을 크게 줄인 암호화폐 보관 방식입니다."],["dao","DAO(탈중앙화 자율 조직)","DAO(탈중앙화 자율 조직)는 경영진 대신 토큰 보유자의 투표와 스마트 컨트랙트 규칙으로 자금 사용과 주요 결정을 내리는 온라인 조직입니다."],["non-custodial-wallet","비수탁형 지갑(Non-custodial Wallet, 개인 지갑)","비수탁형 지갑은 거래소 같은 제3자가 아니라 사용자 본인이 개인 키와 시드 문구를 직접 보관하고 관리하는 암호화폐 지갑입니다."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"내 코인은 어디에 있을까: 거래소 vs 지갑"},"coin":null,"tool":null,"cta":false},"dao":{"slug":"dao","cat":"defi","en":"DAO (decentralized autonomous organization)","contentLocale":"ko","term":"DAO(탈중앙화 자율 조직)","aka":["다오","탈중앙화 자율 조직","DAO"],"short":"DAO(탈중앙화 자율 조직)는 경영진 대신 토큰 보유자의 투표와 스마트 컨트랙트 규칙으로 자금 사용과 주요 결정을 내리는 온라인 조직입니다.","body":[["대부분의 DAO는 ",["거버넌스 토큰","governance-token"],"을 기준으로 투표권을 나눕니다. 누군가 수수료 변경, 금고 자금 지출, 새 체인 확장 같은 제안을 올리면 정해진 기간 동안 투표하고, 정족수와 찬성 비율을 넘으면 통과됩니다. 유니스왑, 에이브 등 주요 ",["디파이","defi"]," 프로토콜이 DAO 형태로 운영됩니다."],["투표는 비용이 들지 않는 오프체인 투표로 의견을 모은 뒤 온체인 투표나 ",["멀티시그","multisig-wallet"]," 실행으로 확정하는 경우가 많습니다. 통과된 제안이 실행되기 전 일정 기간 대기하는 타임락을 두어 문제 있는 제안을 막을 시간을 확보하기도 합니다."],["현실의 DAO는 완전히 평등하지 않습니다. 토큰이 소수 ",["고래","whale"],"나 초기 투자자에게 몰려 있으면 결정도 그들이 좌우하고, 투표 참여율이 낮은 경우도 흔합니다. 법적 지위는 국가마다 다르게 다뤄집니다."]],"example":["총 투표 가능 토큰이 1,000,000개이고 정족수 4%, 과반 찬성으로 통과되는 DAO를 가정합니다. 금고에서 50만 USDC를 개발 지원금으로 쓰자는 제안에 찬성 55,000표, 반대 20,000표가 모였습니다. 총 75,000표로 정족수 40,000표를 넘었고 찬성 비율이 약 73%라 통과됩니다. 이후 48시간 타임락이 지나면 멀티시그나 ",["컨트랙트","smart-contract"],"가 자금을 실제로 보냅니다. 전체 토큰의 7.5%만 투표했다는 점도 함께 볼 부분입니다."],"mistakes":["DAO라는 이름만 보고 운영이 완전히 탈중앙화됐다고 믿습니다.","거버넌스 토큰을 사면 프로토콜 수익을 자동으로 배당받는다고 생각합니다.","투표 일정과 제안 내용을 확인하지 않아 내 토큰에 불리한 결정을 놓칩니다."],"faq":[{"q":"DAO에 참여하려면 무엇이 필요한가요?","a":"보통 해당 DAO의 거버넌스 토큰과 개인 지갑이 필요합니다. 토큰을 보유하거나 다른 사람에게 투표권을 위임해 제안에 투표할 수 있습니다."},{"q":"DAO는 법적으로 회사인가요?","a":"국가와 구조에 따라 다르게 취급됩니다. 일부 지역은 DAO를 위한 법인 형태를 마련했지만, 많은 DAO는 별도 재단이나 법인을 함께 운영합니다."}],"title":"DAO란? 탈중앙화 자율 조직 뜻과 투표 방식","description":"DAO(탈중앙화 자율 조직)의 뜻과 제안·투표·실행 과정, 정족수와 타임락, 현실에서의 한계를 예시로 설명합니다.","related":[["governance-token","거버넌스 토큰(Governance Token)","거버넌스 토큰은 보유량에 비례해 프로토콜이나 DAO의 주요 결정에 투표할 권리를 주는 토큰입니다."],["multisig-wallet","멀티시그 지갑(Multisig Wallet)","멀티시그 지갑은 여러 개의 개인 키 가운데 정해진 수 이상이 함께 서명해야 송금할 수 있는 지갑으로, 키 하나가 유출돼도 자산을 옮길 수 없게 합니다."],["smart-contract","스마트 컨트랙트(Smart Contract)","스마트 컨트랙트는 블록체인에 배포되어 미리 정한 조건이 충족되면 자동으로 실행되는 프로그램으로, 중개자 없이 거래와 규칙을 처리합니다."],["defi","디파이(DeFi, 탈중앙화 금융)","디파이(DeFi)는 은행이나 거래소 같은 중개자 없이 블록체인 위 스마트 컨트랙트로 거래, 대출, 예치 같은 금융 서비스를 제공하는 생태계입니다."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"apr-vs-apy":{"slug":"apr-vs-apy","cat":"defi","en":"APR vs APY","contentLocale":"ko","term":"APR과 APY의 차이","aka":["APR","APY","연이율","연수익률"],"short":"APR은 복리를 반영하지 않은 단순 연이율이고, APY는 받은 이자를 다시 굴리는 복리 효과까지 반영한 연 수익률입니다.","body":[["같은 조건이라도 APY는 APR보다 높게 보입니다. 이자를 자주 재투자할수록, 즉 복리 주기가 짧을수록 두 숫자의 차이가 커집니다. ",["거래소 예치 상품","crypto-earn"],"이나 ",["디파이","defi"]," 화면은 둘 중 하나만 크게 보여 주는 경우가 많아 어떤 기준인지 확인해야 합니다."],["APY는 이자가 자동으로 재예치되거나 사용자가 직접 재투자한다는 가정에서만 성립합니다. 디파이처럼 재예치에 ",["가스비","gas-fee"],"가 들면 실제 수익은 APY보다 낮아질 수 있습니다."],["또한 두 숫자 모두 현재 조건을 연환산한 추정치인 경우가 많습니다. 변동 금리, 보상 토큰 가격, 참여 자금 규모가 바뀌면 실제 1년 수익은 표시된 수치와 달라집니다. ",["펀딩비","funding-rate"],"를 연환산해 비교할 때도 같은 원리가 적용됩니다."]],"example":"10,000 USDT를 APR 12%로 1년 맡긴다고 가정합니다. 복리 없이 받으면 이자는 1,200 USDT입니다. 매달 1%씩 이자를 받아 바로 재예치하면 APY는 약 12.68%로 이자는 약 1,268 USDT가 됩니다. 매일 복리라면 APY는 약 12.75%, 이자는 약 1,275 USDT입니다. 차이는 크지 않아 보여도 금액과 기간이 커질수록 벌어지며, 재예치마다 1 USDT의 비용이 든다면 매일 복리는 오히려 손해입니다.","mistakes":["APR 상품과 APY 상품의 숫자를 그대로 비교합니다.","재예치 비용을 계산하지 않고 APY를 그대로 기대합니다.","표시된 연 수익률이 1년 내내 고정된다고 생각합니다."],"faq":[{"q":"APR과 APY 중 어느 것이 더 정확한가요?","a":"둘 다 맞는 표현이지만 계산 기준이 다릅니다. 복리로 재투자할 계획이면 APY, 이자를 꺼내 쓸 계획이면 APR이 실제 결과에 더 가깝습니다."},{"q":"APR을 APY로 바꾸는 공식이 있나요?","a":"APY는 1 더하기 APR 나누기 복리 횟수를 복리 횟수만큼 거듭제곱한 뒤 1을 빼서 구합니다. 예를 들어 APR 12%를 월복리로 바꾸면 약 12.68%입니다."}],"title":"APR과 APY 차이는? 단리·복리 수익률 계산","description":"APR과 APY의 뜻과 차이, 복리 주기에 따라 수익이 달라지는 계산 예시, 표시 수익률을 볼 때 주의할 점을 정리합니다.","related":[["staking","스테이킹(Staking)","스테이킹은 지분증명(PoS) 블록체인에서 코인을 맡겨 네트워크 검증에 참여하거나 검증인에게 위임하고 그 대가로 보상을 받는 방법입니다."],["yield-farming","일드 파밍(Yield Farming)","일드 파밍은 디파이 프로토콜에 자산을 예치하거나 유동성을 공급하고 그 대가로 이자, 수수료, 보상 토큰을 받아 수익을 쌓는 전략입니다."],["crypto-earn","거래소 예치 상품(Crypto Earn)","거래소 예치 상품은 거래소에 코인을 맡기면 정해진 기간이나 자유 입출금 조건으로 이자 성격의 보상을 주는 상품군을 말합니다."],["funding-rate","펀딩비(Funding Rate)","펀딩비는 무기한 선물에서 롱과 숏 포지션 보유자가 일정 간격마다 서로 주고받는 비용으로, 선물 가격이 현물 가격에서 크게 벗어나지 않도록 하는 장치입니다."]],"lesson":null,"coin":null,"tool":null,"cta":false},"algorithmic-stablecoin":{"slug":"algorithmic-stablecoin","cat":"stablecoins","en":"Algorithmic stablecoin","contentLocale":"ko","term":"알고리즘 스테이블코인","aka":["알고리즘형 스테이블코인","Algorithmic stablecoin"],"short":"알고리즘 스테이블코인은 충분한 준비금 없이 코드와 시장 인센티브로 공급량을 늘리고 줄여 1달러 가치를 유지하려는 스테이블코인입니다.","body":[["일반적인 구조는 ",["스테이블코인","stablecoin"],"과 짝이 되는 ",["변동성","volatility"]," 토큰을 함께 두는 방식입니다. 스테이블코인이 1달러보다 비싸면 새로 발행해 팔도록 유도하고, 1달러보다 싸면 스테이블코인을 소각하고 짝 토큰을 받도록 유도합니다. 차익을 노리는 거래자가 가격을 다시 1달러로 끌어당긴다는 논리입니다."],"문제는 이 구조가 시장의 신뢰에 크게 의존한다는 점입니다. 매도가 한꺼번에 몰리면 짝 토큰이 대량 발행되고, 그 가격이 무너지면서 스테이블코인도 함께 무너지는 악순환이 생길 수 있습니다. 2022년 5월 테라의 UST와 루나 붕괴가 이 위험을 보여 준 대표 사례입니다.","그 이후 많은 프로젝트가 순수 알고리즘 방식 대신 일부 담보를 섞은 하이브리드 구조를 택했습니다. 이름에 스테이블이 들어가 있어도 무엇이 1달러를 뒷받침하는지 백서와 담보 현황으로 확인해야 합니다."],"example":"어떤 알고리즘 스테이블코인이 0.98달러에 거래된다고 가정합니다. 프로토콜은 이 코인 1개를 소각하면 1달러어치의 짝 토큰을 줍니다. 거래자는 1,000개를 980달러에 사서 소각하고 1,000달러어치 짝 토큰을 받아 20달러를 법니다. 하지만 짝 토큰을 시장에 팔 때 가격이 10% 빠져 있다면 900달러만 남아 오히려 80달러 손해가 납니다. 이런 상황이 퍼지면 가격 회복 장치가 멈춥니다.","mistakes":["높은 예치 이자만 보고 그 이자가 어디서 나오는지 확인하지 않습니다.","알고리즘 스테이블코인을 준비금 기반 스테이블코인과 같은 안전 자산으로 취급합니다.","작은 디페깅을 매수 기회로만 보고 악순환의 신호일 가능성을 무시합니다."],"faq":[{"q":"알고리즘 스테이블코인은 왜 위험하다고 하나요?","a":"가격을 지키는 힘이 외부 준비금이 아니라 시장 참여자의 신뢰와 짝 토큰의 가치에서 나오기 때문입니다. 신뢰가 무너지면 가격 방어 장치가 함께 약해집니다."},{"q":"UST 사태는 무엇이었나요?","a":"2022년 5월 테라 생태계의 알고리즘 스테이블코인 UST가 1달러 고정을 잃고, 짝 토큰 루나가 대량 발행되며 둘 다 가치가 거의 사라진 사건입니다."}],"title":"알고리즘 스테이블코인이란? 작동 원리와 UST 사례","description":"알고리즘 스테이블코인의 뜻과 공급 조절 원리, 붕괴가 일어나는 구조를 예시로 쉽게 설명합니다.","related":[["depeg","디페깅(Depeg)","디페깅은 1달러 같은 기준 가치에 고정(페깅)되도록 설계된 스테이블코인이나 자산의 가격이 그 기준에서 눈에 띄게 벗어나는 현상입니다."],["stablecoin","스테이블코인(Stablecoin)","스테이블코인은 미국 달러 같은 법정화폐나 다른 자산의 가치에 가격을 고정하도록 설계된 암호화폐로, USDT와 USDC가 대표적입니다."],["crypto-backed-stablecoin","암호화폐 담보 스테이블코인","암호화폐 담보 스테이블코인은 달러 예금 대신 ETH 같은 암호화폐를 담보로 맡기고, 담보 가치보다 적은 양만 발행하는 스테이블코인입니다."],["synthetic-dollar","합성 달러(델타 중립 스테이블코인)","합성 달러는 현물 암호화폐를 보유하면서 같은 규모의 선물 숏 포지션으로 가격 변동을 상쇄해 1달러 가치를 만드는 델타 중립형 스테이블코인입니다."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT는 달러일까요? 코인을 살 때 왜 항상 보일까요?"},"coin":null,"tool":null,"cta":false}});
